function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function values(v) {
  return String(v || '').split(',').map(s => s.trim()).filter(Boolean);
}
// FIX 2026-08-01 (Fehleranalyse A1, SQL-Injection): das alte pgArr() escapte nur doppelte
// Anfuehrungszeichen, nicht das einfache Anfuehrungszeichen, mit dem das Array-Literal selbst
// umschlossen wurde - ein Apostroph in Keywords/Ausschlussbegriffen brach die SQL-Struktur auf
// (z.B. "a'); DROP TABLE trading.watchlist;--"). Jetzt ueber Postgres' eigene ARRAY[...]-Syntax
// gebaut, jedes Element einzeln durch das bereits korrekt escapende pgStr() - kein
// String-Literal-Bruch mehr moeglich.
function pgArr(v) {
  const arr = values(v);
  if (!arr.length) return `'{}'::text[]`;
  return `ARRAY[` + arr.map(x => pgStr(x)).join(',') + `]::text[]`;
}
function pgJson(v) {
  return `'` + JSON.stringify(values(v)).replace(/'/g, `''`) + `'::jsonb`;
}

// FIX 2026-08-01 (Fehleranalyse A3/A4): serverseitige Validierung statt nur clientseitiger
// Formularpruefung. Ungueltige Eingaben erzeugen jetzt einen sichtbaren Fehlerstatus
