function validateKeywordList(raw, fieldLabel, errors) {
  const arr = values(raw);
  if (arr.length > 30) errors.push(fieldLabel + ': maximal 30 Eintraege erlaubt.');
  for (const k of arr) {
    if (k.length > 50) { errors.push(fieldLabel + ': ein Eintrag ist laenger als 50 Zeichen.'); break; }
  }
}

