  sql = 'SELECT 1;';
  validation_error = 'Ungueltiges Tickerformat (erlaubt: Grossbuchstaben/Ziffern/Punkt/Bindestrich, max. 15 Zeichen).';
} else if (action === 'add' || action === 'edit') {
  const name = String(j.name || '').trim();
  const sektor = String(j.sektor || '').trim();
  const errors = [];
  if (!name) errors.push('Name darf nicht leer sein.');
  if (name.length > 200) errors.push('Name ist laenger als 200 Zeichen.');
  if (sektor.length > 100) errors.push('Sektor ist laenger als 100 Zeichen.');
  validateKeywordList(j.keywords, 'Keywords', errors);
  validateKeywordList(j.exclude_keywords, 'Ausschlussbegriffe', errors);

  if (errors.length) {
    sql = 'SELECT 1;';
    validation_error = errors.join(' ');
  } else if (action === 'add') {
    sql = `BEGIN;
      INSERT INTO trading.watchlist (ticker, name, sektor, keywords, exclude_keywords, active)
      VALUES (${pgStr(ticker)}, ${pgStr(name)}, ${pgStr(sektor)}, ${pgArr(j.keywords)}, ${pgArr(j.exclude_keywords)}, TRUE)
      ON CONFLICT (ticker) DO UPDATE SET
        name = EXCLUDED.name, sektor = EXCLUDED.sektor, keywords = EXCLUDED.keywords,
        exclude_keywords = EXCLUDED.exclude_keywords, active = TRUE, updated_at = now();
      INSERT INTO trading.stock_instruments
        (ticker, name, sektor, aktiv, aliases_json, exclude_patterns_json, updated_at)
      VALUES (${pgStr(ticker)}, ${pgStr(name)}, ${pgStr(sektor)}, TRUE, ${pgJson(j.keywords)}, ${pgJson(j.exclude_keywords)}, now())
      ON CONFLICT (ticker) DO UPDATE SET
        name = EXCLUDED.name, sektor = EXCLUDED.sektor, aktiv = TRUE,
        aliases_json = EXCLUDED.aliases_json, exclude_patterns_json = EXCLUDED.exclude_patterns_json,
        updated_at = now();
      COMMIT;`;
  } else {
    sql = `BEGIN;
      UPDATE trading.watchlist SET
        name = ${pgStr(name)}, sektor = ${pgStr(sektor)}, keywords = ${pgArr(j.keywords)},
        exclude_keywords = ${pgArr(j.exclude_keywords)}, updated_at = now()
        WHERE ticker = ${pgStr(ticker)};
      UPDATE trading.stock_instruments SET
        name = ${pgStr(name)}, sektor = ${pgStr(sektor)}, aliases_json = ${pgJson(j.keywords)},
        exclude_patterns_json = ${pgJson(j.exclude_keywords)}, updated_at = now()
        WHERE ticker = ${pgStr(ticker)};
      COMMIT;`;
  }
